#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
use soe_esm::{FileHeader,GlobalFormId,LoadOrder,Plugin,Record,Tag};use soe_game::Game;use soe_papyrus::{asm::{ident,none,s,FunctionBuilder,ScriptBuilder},Opcode::{CallMethod,Return},Value};
fn id(n:u32)->GlobalFormId{GlobalFormId{file:0,object:n}}
fn call(g:&mut Game,scroll:u32,source:Value,target:Value){let script=format!("Scr45Adv{scroll}");let bytes=ScriptBuilder::new(&script,"Scroll").function(FunctionBuilder::new("Run","None").global().param("scroll","Scroll").param("source","ObjectReference").param("target","ObjectReference").local("r","None").ins(CallMethod,vec![s("Cast"),ident("scroll"),ident("r"),ident("source"),ident("target")]).ins(Return,vec![none()]).build()).bytes();g.load_script(&bytes).unwrap();let form=Value::Object(g.object_of_form(id(scroll)));let t=g.vm.call_global(&script,"Run",&[form,source,target]).unwrap();assert!(g.run_until_idle(32));assert_eq!(g.vm.thread_result(t),Some(Value::None));}
#[test]fn scr_45_missing_scroll_receiver_has_no_cast_side_effect(){let mut p=Plugin::new(FileHeader::default());p.push_top(Record::new(Tag(*b"STAT"),0x800));let mut order=LoadOrder::new();order.add("MissingScroll.esm",p).unwrap();let mut g=Game::new(order);let source=Value::Object(g.object_of_form(id(0x801)));let target=Value::Object(g.object_of_form(id(0x802)));call(&mut g,0x800,source,target);assert!(g.world().spell_casts.is_empty());assert_eq!(g.world().active_effects().count(),0);}
